Method.Implementation:
$$$LOGINFO("In ProcessPhcDbMergeRequest " _ pRequest.oldSubscriberNumber _ ", " _ pRequest.newSubscriberNumber)
#dim tSC As %Status=$$$OK
#dim tRTs As %ListOfObjects
#dim tResultSet,snap As EnsLib.SQL.Snapshot
set ioParms=4
set ioParms(1)=pRequest.firstName	//DND_Dental_835
set ioParms(2)=pRequest.lastName
set ioParms(3)=pRequest.DOB  // Change to format the DOB
set ioParms(4)=pRequest.grpID		

//1 represents SQL_CHAR,4 represents SQL_INTEGER,6 represents SQL_FLOAT, 8 represents SQL_DOUBLE, 12 represents SQL_VARCHAR

set ioParms(1,"SqlType")=12
set ioParms(2,"SqlType")=12
set ioParms(3,"SqlType")=4
set ioParms(4,"SqlType")=12
//dbo.IHCSP_SELECT_NEWENROLLMENTS(?,?,?,?)	

Set tQuery="{call dbo.IHCSP_SELECT_NEWENROLLMENTS(?,?,?,?)}"


Set snap=##class(EnsLib.SQL.Snapshot).%New()
Set snap.MaxRowsToGet=-1
Set tRTs=##class(%Library.ListOfObjects).%New()
Do tRTs.Insert(snap)
try
{
	Set tSC = ..Adapter.ExecuteProcedureParmArray(.tRTs,.tOutParms,tQuery,"iiii#",.ioParms)

  	$$$TRACE(tOutParms_"Stored Procedure Call status "_tSC) 

  	If ($$$ISOK(tSC)){
	  	set tResultSet=tRTs.GetAt(1)
	  	$$$TRACE(tResultSet_"Resultset rowcount"_tResultSet.RowCount)
	  	$$$TRACE(" Column Count of the result set"_tResultSet.ColCount)

	  	if ('$ISOBJECT(tResultSet)||tResultSet.RowCount=0){
	  	    set tSC=$$$ERROR("ITFSHKBEFT001","Error in result Set from the SQL call to SH or Rowcount zero ,   Error Code : "_tOutParms.GetAt(1)_"   Error Description : "_tOutParms.GetAt(2))
	  	    quit

	  	}else {

		  	$$$TRACE(" obj count "_tRTs.Count())
		  	$$$TRACE(" Row Count of the result set"_tResultSet.RowCount)
		  	$$$TRACE(" Column Count of the result set"_tResultSet.ColCount)

		  	Set pResponse = ##class(Ens.StringRequest).%New()
		  	If pResultSet.%Next(.sc)
		  	{
			  	set pResponse.StringValue="TRUE"
		  	}
		  	Else
		  	{
			  	set pResponse.StringValue="FALSE"
		  	}
		  	Do pResponse.%Save()

	  	}
  	}
  	Else
  	{
	  	set tSC=$$$ERROR("ITFSHKBEFT002","Error in executing the storedprocedure ,   Error  : "_tSC)
  	}
}
catch e
{
	$$$TRACE("Exception: " _ e)
	set tSC = $$$ERROR("ITFSHKBEFT003","Unknown exception in executing the storedprocedure ,   Error  : "_e)
}
quit tSC
